class Solution:
    def countSubarrays(self, nums: List[int], a: int, b: int) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            x = y = 0
            for j in range(i, n):
                if nums[j] % 2:
                    y += 1
                else:
                    x += 1
                if y > 0 and b * x <= a * y:
                    ans += 1
        return ans

