class Solution:
    def countSubarrays(self, nums: List[int], a: int, b: int) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        o = [0] * (n + 1)
        e = od = 0
        for i, v in enumerate(nums):
            if v % 2:
                od += 1
            else:
                e += 1
            p[i + 1] = b * e - a * od
            o[i + 1] = od
        s = sorted(set(p))
        m = len(s)
        rank = {v: i + 1 for i, v in enumerate(s)}
        bit = [0] * (m + 1)
        def upd(i):
            while i <= m:
                bit[i] += 1
                i += i & -i
        def qry(i):
            r = 0
            while i > 0:
                r += bit[i]
                i -= i & -i
            return r
        ans = 0
        for v in p:
            ans += qry(m) - qry(rank[v] - 1)
            upd(rank[v])
        i = 0
        while i <= n:
            j = i
            while j + 1 <= n and o[j + 1] == o[i]:
                j += 1
            for u in range(i, j + 1):
                for w in range(u + 1, j + 1):
                    if p[w] <= p[u]:
                        ans -= 1
            i = j + 1
        return ans

