            p[i + 1] = b * e - a * od;
            o[i + 1] = (int)od;
        }
        vector<long long> s(p.begin(), p.end());
        sort(s.begin(), s.end());
        s.erase(unique(s.begin(), s.end()), s.end());
        int m = s.size();
        vector<int> bit(m + 1, 0);
        auto upd = [&](int i) { for (; i <= m; i += i & -i) bit[i]++; };
        auto qry = [&](int i) { long long r = 0; for (; i > 0; i -= i & -i) r += bit[i]; return r; };
        long long ans = 0;
        for (long long v : p) {
            int r = lower_bound(s.begin(), s.end(), v) - s.begin() + 1;
            ans += qry(m) - qry(r - 1);
            upd(r);
        }
        for (int i = 0; i <= n;) {
            int j = i;
            while (j + 1 <= n && o[j + 1] == o[i]) j++;
            for (int u = i; u <= j; u++)
                for (int w = u + 1; w <= j; w++)
                    if (p[w] <= p[u]) ans--;
            i = j + 1;
        }
        return ans;
    }
};

