class Solution {
    public long countSubarrays(int[] nums, int a, int b) {
        int n = nums.length;
        long[] p = new long[n + 1];
        int[] o = new int[n + 1];
        long e = 0, od = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] % 2 == 1) od++; else e++;
            p[i + 1] = b * e - a * od;
            o[i + 1] = (int) od;
        }
        long[] s = p.clone();
        Arrays.sort(s);
        int m = 0;
        for (int i = 0; i < s.length; i++)
            if (i == 0 || s[i] != s[m - 1]) s[m++] = s[i];
        int[] bit = new int[m + 1];
        java.util.function.IntUnaryOperator unused = null;
        long ans = 0;
        for (int k = 0; k <= n; k++) {
            int lo = 0, hi = m - 1, r = 0;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (s[mid] <= p[k]) { r = mid + 1; lo = mid + 1; } else hi = mid - 1;
            }
            for (int i = m; i > 0; i -= i & -i) ans -= bit[i];
            for (int i = r - 1; i > 0; i -= i & -i) ans += bit[i];
            for (int i = r; i <= m; i += i & -i) bit[i]++;
        }
        for (int i = 0; i <= n;) {
            int j = i;
            while (j + 1 <= n && o[j + 1] == o[i]) j++;
            for (int u = i; u <= j; u++)
                for (int w = u + 1; w <= j; w++)
                    if (p[w] <= p[u]) ans--;
            i = j + 1;
        }
        return ans;
    }
}

