var countSubarrays = function(nums, a, b) {
    const n = nums.length;
    const p = new Array(n + 1).fill(0), o = new Array(n + 1).fill(0);
    let e = 0, od = 0;
    for (let i = 0; i < n; i++) {
        if (nums[i] % 2 === 1) od++; else e++;
        p[i + 1] = b * e - a * od;
        o[i + 1] = od;
    }
    const s = [...new Set(p)].sort((x, y) => x - y);
    const m = s.length;
    const bit = new Array(m + 1).fill(0);
    const upd = i => { for (; i <= m; i += i & -i) bit[i]++; };
    const qry = i => { let r = 0; for (; i > 0; i -= i & -i) r += bit[i]; return r; };
    let ans = 0;
    for (const v of p) {
        const r = s.indexOf(v) + 1;
        ans += qry(m) - qry(r - 1);
        upd(r);
    }
    for (let i = 0; i <= n;) {
        let j = i;
        while (j + 1 <= n && o[j + 1] === o[i]) j++;
        for (let u = i; u <= j; u++)
            for (let w = u + 1; w <= j; w++)
                if (p[w] <= p[u]) ans--;
        i = j + 1;
    }
    return ans;
};
